import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"工作台","description":"","frontmatter":{},"headers":[],"relativePath":"backend/workbench.md","filePath":"backend/workbench.md","lastUpdated":1794049926000}`),a={name:`backend/workbench.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="工作台" tabindex="-1">工作台 <a class="header-anchor" href="#工作台" aria-label="Permalink to “工作台”">​</a></h1><p>本页说明工作台小组件的提供者契约、操作、已登记的小组件与布局同步，适用于为能力包添加小组件的后端开发者。</p><p>Workbench 是 Tier 3 的可选模块（<code>BasicApp:Modules:Workbench:Enabled</code>，缺省开）：各包登记自己的小组件并负责取数，Workbench 只负责汇总、核权限与转发，自己没有表也没有权限码。</p><h2 id="提供者契约" tabindex="-1">提供者契约 <a class="header-anchor" href="#提供者契约" aria-label="Permalink to “提供者契约”">​</a></h2><p><code>Contracts/Workbench/IWorkbenchWidgetProvider</code>：</p><table tabindex="0"><thead><tr><th>成员</th><th>说明</th></tr></thead><tbody><tr><td><code>Widgets</code></td><td>本包登记的小组件（<code>WorkbenchWidget</code>）：键、取数形态与所需权限码（为空即登录就能看）</td></tr><tr><td><code>GetAsync(key, query, context)</code></td><td>按键返回 <code>WorkbenchWidgetData</code>；权限已由工作台核过，键一定是本包登记的</td></tr></tbody></table><p>取数形态 <code>WorkbenchWidgetKind</code>：</p><table tabindex="0"><thead><tr><th>形态</th><th>数据</th></tr></thead><tbody><tr><td><code>Metric</code></td><td>指标值与昨日值（前端算涨跌）</td></tr><tr><td><code>Chart</code></td><td>类目加序列，或构成</td></tr><tr><td><code>List</code></td><td>条目（可带总数）</td></tr></tbody></table><p>数据只取当前一侧（租户主体是本租户、平台主体是平台一侧），与各包列表页同一口径。标题、图标、宽度、图表类型等呈现全在前端，后端只给数据。</p><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to “操作”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>workbench.widgets</code></td><td><code>GET /api/workbench:widgets</code>，自助、只读：按调用方的权限列出可见的小组件</td></tr><tr><td><code>workbench.widget-data</code></td><td><code>GET /api/workbench:widget-data</code>，自助、只读：找不到键 <code>WORKBENCH_NOTFOUND_001</code>，没有权限 <code>WORKBENCH_DENIED_001</code>，再交给登记它的包取数</td></tr></tbody></table><p><code>workbench.widget-data</code> 带统计天数 <code>days</code>（1–366，缺省 30，趋势与构成类用）与查看者的时区偏移 <code>offset</code>（分钟，-840–840，前端取应用时区此刻的偏移）：「今日」「按日」这类统计按查看者的本地日计算（库里按 UTC 小时分组再换算）。</p><h2 id="已登记的小组件-16-个" tabindex="-1">已登记的小组件（16 个） <a class="header-anchor" href="#已登记的小组件-16-个" aria-label="Permalink to “已登记的小组件（16 个）”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>键</th><th>形态</th><th>权限</th></tr></thead><tbody><tr><td>Auditing</td><td><code>auditing.logins-today</code>、<code>auditing.requests-today</code>、<code>auditing.exceptions-today</code></td><td>Metric</td><td>对应日志的 <code>read</code></td></tr><tr><td>Auditing</td><td><code>auditing.login-trend</code>、<code>auditing.login-failures</code></td><td>Chart</td><td><code>auditing.login-logs.read</code></td></tr><tr><td>Auditing</td><td><code>auditing.request-kpi</code>、<code>auditing.request-heatmap</code>、<code>auditing.top-operations</code></td><td>Chart</td><td><code>auditing.access-logs.read</code></td></tr><tr><td>Auditing</td><td><code>auditing.exception-types</code></td><td>Chart</td><td><code>auditing.exception-logs.read</code></td></tr><tr><td>Identity</td><td><code>identity.online-users</code></td><td>Metric</td><td><code>identity.sessions.read</code></td></tr><tr><td>Identity</td><td><code>identity.session-devices</code></td><td>Chart</td><td><code>identity.sessions.read</code></td></tr><tr><td>Files</td><td><code>files.storage-mix</code></td><td>Chart</td><td><code>files.files.read</code></td></tr><tr><td>Maintenance</td><td><code>maintenance.job-runs</code></td><td>Chart</td><td><code>maintenance.job-runs.read</code></td></tr><tr><td>Notification</td><td><code>notification.announcements</code></td><td>List</td><td>—（本人收件箱里最近的几条）</td></tr><tr><td>Notification</td><td><code>notification.deliveries</code></td><td>Chart</td><td><code>notification.emails.read</code>（短信那部分另要 <code>notification.sms.read</code>）</td></tr><tr><td>Workflow</td><td><code>workflow.todo</code></td><td>List</td><td>—（Workflow 开着才有）</td></tr></tbody></table><p>前端据此渲染公告轮播、今日统计与访问概况、在线设备、登录失败原因、登录趋势、存储占用、热门操作、访问时段、作业执行、异常类型、消息发送等图表；图表壳带取数中、出错与无数据的占位。</p><h2 id="看板布局" tabindex="-1">看板布局 <a class="header-anchor" href="#看板布局" aria-label="Permalink to “看板布局”">​</a></h2><p>不另建表，存放在 Identity 的用户设置中（<code>user-settings</code>，场景 <code>Page</code>、键 <code>workbench:widgets</code>），本地即时保存并跨端同步：同步开关在「偏好设置 › 同步 › 仪表盘看板」，开着时以后端那份为准，其他设备改了经 <code>UserSettingChanged</code> 实时应用，点「完成」且有改动才落地。</p><h2 id="开关" tabindex="-1">开关 <a class="header-anchor" href="#开关" aria-label="Permalink to “开关”">​</a></h2><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;BasicApp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Modules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Workbench&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } } }</span></span></code></pre></div><p>关掉后宿主不装 <code>WorkbenchFeature</code>，菜单里没有工作台；前端把 <code>VITE_HOME_PATH</code> 留空，登录后落到第一个有权限的页面。各包的提供者照常登记，没有消费方。</p><h2 id="为能力包添加小组件" tabindex="-1">为能力包添加小组件 <a class="header-anchor" href="#为能力包添加小组件" aria-label="Permalink to “为能力包添加小组件”">​</a></h2><ol><li>在包的 <code>Infrastructure/</code> 实现 <code>IWorkbenchWidgetProvider</code>，登记键（<code>&lt;包&gt;.&lt;名&gt;</code>）、形态与权限码；</li><li>在 <code>Configure</code> 里 <code>context.Services.AddScoped&lt;IWorkbenchWidgetProvider, XxxWidgets&gt;()</code>；</li><li>在前端 <code>src/modules/workbench</code> 里加呈现（标题、图标、尺寸、图表类型与文案）。</li></ol><p>可选模块不改工作台：在模块的 <code>setup.ts</code> 里以 <code>registerWorkbenchWidget</code>（<code>~/stores</code>）登记列表型小组件——看板上的键、后端小组件键、标题 / 说明 / 空态文案键、图标、缺省宽度、所属页面与「查看全部」的路由；看板用同一个列表外观渲染（标题栏是总数与「查看全部」，正文是最近几条），排在内置小组件之后、进缺省看板，按所属页面是否下发决定显隐，模块关掉时随之隐藏。工作流的「我的待办」就是这样接的。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./introduction">架构总览</a> · <a href="./settings">系统设置</a> · <a href="./../frontend/introduction">前端框架简介</a></li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};